import itertools

def ccw(A, B, C):
    """Check if three points are in counter-clockwise order"""
    return (C[1] - A[1]) * (B[0] - A[0]) > (B[1] - A[1]) * (C[0] - A[0])

def segments_intersect(A, B, C, D):
    """Check if line segment AB and CD intersect"""
    return ccw(A, C, D) != ccw(B, C, D) and ccw(A, B, C) != ccw(A, B, D)

def has_crossing(rebels, bases, matching):
    """Check if the given matching has any crossing paths"""
    # matching is a permutation of base indices
    # rebels[i] is matched to bases[matching[i]]

    n = len(rebels)

    for i in range(n):
        for j in range(i + 1, n):
            # Path 1: rebels[i] to bases[matching[i]]
            # Path 2: rebels[j] to bases[matching[j]]

            if segments_intersect(rebels[i], bases[matching[i]],
                                  rebels[j], bases[matching[j]]):
                return True

    return False

