def mod_pow(base, exp, mod):
    result = 1
    base = base % mod
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        exp = exp >> 1
        base = (base * base) % mod
    return result

def comb(n, r, mod):
    if r > n or r < 0:
        return 0
    if r == 0 or r == n:
        return 1

    numerator = 1
    denominator = 1
    for i in range(r):
        numerator = (numerator * (n - i)) % mod
        denominator = (denominator * (i + 1)) % mod

    return (numerator * mod_pow(denominator, mod - 2, mod)) % mod

