def find_element(n, k):
    # Find the k-th element (1-indexed) in the sequence after n-1 steps
    # The sequence has structure: seq(n-1) + [n] + seq(n-1)
    if n == 1:
        return 1

    # Length of sequence at step n-1
    len_prev = (1 << (n - 1)) - 1  # 2^(n-1) - 1

    if k <= len_prev:
        # Left part: first copy of seq(n-1)
        return find_element(n - 1, k)
    elif k == len_prev + 1:
        # Middle element: n
        return n
    else:
        # Right part: second copy of seq(n-1)
        return find_element(n - 1, k - len_prev - 1)

